public class Solution {
    public static String changeFor(int cents) {
        int quarters = cents / 25;
        cents %= 25;
        int dimes = cents / 10;
        cents %= 10;
        int nickels = cents / 5;
        int pennies = cents % 5;
        return quarters + "q " + dimes + "d " + nickels + "n " + pennies + "p";
    }
}

